import java.util.function.Supplier;

final class NaiveMemo<T> implements Supplier<T> {
    private final Supplier<T> source;
    private boolean done;
    private T value;

    NaiveMemo(Supplier<T> source) { this.source = source; }

    @Override
    public T get() {
        if (!done) {                 // (1)
            value = source.get();    // (2)
            done = true;             // (3)
        }
        return value;
    }
}

